package pricing

import "fmt"

type Item struct {
	Price float64
	Qty   int
}

func CalcTotal(items []Item, taxRate float64) float64 {
	total := 0.0
	for _, i := range items {
		total += i.Price * float64(i.Qty)
	}
	return total * (1 + taxRate)
}

func FormatPrice(amount float64) string {
	return fmt.Sprintf("$%.2f", amount)
}

